.ds-button {color:var(--text);}
.ds-button {display: inline-flex; justify-content: center; align-items: center; gap: 8px; padding: 12px 18px; min-height: 46px; font-weight: 600; border: 1px solid var(--line-strong); border-radius: 5px; background: var(--surface); font-size: 15px;}
.ds-button:hover:not(:disabled) {background: var(--surface-hover);}
.ds-button {font-family:var(--body);line-height:1.5;cursor:pointer;transition:background-color .18s,border-color .18s,color .18s;overflow-wrap:anywhere;-webkit-tap-highlight-color:transparent;}
.ds-button:focus-visible {outline:2px solid var(--gold);outline-offset:4px;}
.ds-button:active:not(:disabled) {filter:brightness(.9);}
.ds-button:disabled {cursor:not-allowed;opacity:.42;}
.ds-button svg {flex-shrink:0;}
@media(prefers-reduced-motion:reduce) {.ds-button {transition:none!important;animation:none!important;}}

