.ds-search-field {display: flex; align-items: center; gap: 10px; border: 1px solid var(--line-strong); border-radius: 5px; padding: 0 12px; color: var(--muted);}
.ds-search-field input {width: 100%; min-width: 0; border: 0; background: transparent; min-height: 48px; outline-offset: 0;}
.ds-search-field{font-family:var(--body);line-height:1.5}.ds-search-field input{font-family:var(--body);font-size:16px;line-height:1.5;color:var(--text);border-radius:5px;caret-color:var(--red-light)}.ds-search-field input::placeholder{color:var(--muted)}.ds-search-field input:focus-visible{outline:2px solid var(--gold);outline-offset:0}.ds-search-field svg{flex-shrink:0}

.ds-main-nav {display: grid; grid-template-columns: repeat(4, 1fr); position: fixed; bottom: 0; left: 0; right: 0; z-index: 20; background: #1b1217; border-top: 1px solid #50303a; padding: 0 10px env(safe-area-inset-bottom); box-shadow: 0 -8px 28px #08050955;}
.ds-main-nav button {display: flex; align-items: center; justify-content: center; flex-direction: column; gap: 5px; min-height: 72px; padding: 10px 3px; border: 0; border-top: 2px solid transparent; background: transparent; color: var(--muted); font-size: 11px;}
.ds-main-nav button[aria-current] {color: var(--rose); border-top-color: var(--red-light); background: linear-gradient(#a32e4120, transparent);}
.ds-main-nav button:hover {color: var(--text);}
.ds-main-nav button {font-family:var(--body);line-height:1.5;cursor:pointer;transition:background-color .18s,border-color .18s,color .18s;overflow-wrap:anywhere;-webkit-tap-highlight-color:transparent;}
