.ds-main-nav button:active:not(:disabled) {filter:brightness(.9);}
.ds-main-nav button:disabled {cursor:not-allowed;opacity:.42;}
.ds-main-nav button svg {flex-shrink:0;}
@media(prefers-reduced-motion:reduce) {.ds-main-nav button {transition:none!important;animation:none!important;}}
.ds-main-nav{position:relative;left:auto;right:auto;bottom:auto;z-index:auto}
@media(min-width:1000px){.ds-main-nav{display:flex;flex-direction:column;width:180px;gap:5px;background:transparent;border:0;box-shadow:none;padding:0}.ds-main-nav button{flex-direction:row;justify-content:flex-start;min-height:52px;gap:15px;padding:12px 20px;border:1px solid transparent;border-radius:5px;font-size:14px}.ds-main-nav button[aria-current]{border-color:#63303a;background:#31171e}}

.ds-active-effects {display: flex; flex-wrap: wrap; gap: 7px; margin: -4px 0 22px;}
.ds-active-effects button {display: flex; align-items: center; gap: 7px; min-height: 44px; padding: 8px 10px; border: 1px solid #6d3440; background: #30161d; color: var(--rose); border-radius: 4px; font-size: 12px;}
.ds-active-effects small {width: 100%; color: var(--muted); font-size: 11px;}
.ds-active-effects button {font-family:var(--body);line-height:1.5;cursor:pointer;transition:background-color .18s,border-color .18s,color .18s;overflow-wrap:anywhere;-webkit-tap-highlight-color:transparent;}
