.ds-active-effects button svg {flex-shrink:0;}
@media(prefers-reduced-motion:reduce) {.ds-active-effects button {transition:none!important;animation:none!important;}}
.ds-active-effects small{font-family:var(--body);line-height:1.5}

.ds-ability {border: 1px solid var(--line-strong); border-radius: 4px; text-align: center; padding: 15px 8px; background: var(--surface);}
.ds-ability > span {color: var(--muted); font-size: 12px;}
.ds-ability strong {display: block; font-size: 30px; font-variant-numeric: tabular-nums; line-height: 1.3;}
.ds-ability small {display: inline-block; font-size: 12px; color: var(--gold); border-top: 1px solid var(--line-strong); padding: 4px 10px 0; margin-top: 5px;}
.ds-ability{font-family:var(--body);line-height:1.5;color:var(--text)}.ds-ability strong{font-weight:600}

.ds-button {display: inline-flex; justify-content: center; align-items: center; gap: 8px; padding: 12px 18px; min-height: 46px; font-weight: 600; border: 1px solid var(--line-strong); border-radius: 5px; background: var(--surface); font-size: 15px;}
.ds-button:hover:not(:disabled) {background: var(--surface-hover);}
.ds-vitality {position: relative; isolation: isolate; min-height: 232px; background: linear-gradient(120deg, #511724, #32141d 65%, #251319); border: 1px solid #853044; border-radius: 8px; padding: 20px; display: grid; grid-template-columns: minmax(0, 1fr) 92px; column-gap: 4px; overflow: hidden;}
.ds-vitality::before {content: ""; position: absolute; pointer-events: none; inset: 6px; border: 1px solid #b9526230; border-radius: 3px; z-index: -1;}
.ds-vitality::after {content: ""; position: absolute; pointer-events: none; right: 21px; top: 0; bottom: 0; width: 1px; background: #b9526230; z-index: -1;}
.ds-vitality-heading h2 {font-size: 15px; color: var(--rose);}
.ds-status-mark {display: block; font-size: 10px; color: #e3adb3; margin-top: 4px;}
.ds-hp-number {display: flex; align-items: center; gap: 12px; font-variant-numeric: tabular-nums; margin: 3px 0 1px;}
.ds-hp-number > strong {font-size: 76px; line-height: 1.12; letter-spacing: -0.05em; font-weight: 500; color: #fff2e7;}
.ds-hp-number > span {font-size: 23px; color: #e7b7bd;}
.ds-hp-number small {display: block; font-size: 11px; color: #e7b7bd;}
.ds-temp-button {padding: 5px 0; display: flex; gap: 6px; align-items: center; background: transparent; border: 0; min-height: 36px; font-size: 11px; color: #eac5ca;}
.ds-blood-vessel {width: 92px; height: 156px; align-self: center; overflow: visible;}
.ds-blood-liquid {transition: transform 0.7s cubic-bezier(0.16, 1, 0.3, 1);}
.ds-hp-actions {display: grid; grid-template-columns: 1.6fr 1fr; gap: 10px; grid-column: 1/-1; margin-top: 14px;}
.ds-damage-button {background: #9f293e; border-color: #c04b60; color: #fff2ed;}
.ds-heal-button {background: #e7d8c6; border-color: #e7d8c6; color: #32191d;}
.ds-heal-button:hover:not(:disabled) {background: #fff0da;}
.ds-damage-button:hover:not(:disabled) {background: #b3364d;}
.ds-vitality{font-family:var(--body);font-size:16px;line-height:1.5;color:var(--text)}.ds-vitality h2{margin:0;font-family:var(--display);font-weight:600;line-height:1.4}.ds-hp-number strong{font-weight:500}.ds-vitality button{font-family:var(--body);line-height:1.5}.ds-temp-button{cursor:pointer}
.ds-vitality button {font-family:var(--body);line-height:1.5;cursor:pointer;transition:background-color .18s,border-color .18s,color .18s;overflow-wrap:anywhere;-webkit-tap-highlight-color:transparent;}
